  app.className = "archery-screen";
  app.innerHTML = `<header class="arch-header"><button class="brand-home" id="arch-home" aria-label="Back to Pinpoise">Pinpoise</button><h1>Poise Archery</h1><button class="arch-text-btn" id="arch-restart">Restart</button></header>
  <div class="arch-hud"><div><b id="arch-round">Target 1 of 3</b><span id="arch-shots" aria-label="Three shots remaining"></span></div><div id="arch-wind">${WIND_ICON}<span></span></div><b id="arch-total">0 <small>pts</small></b></div>
  <div id="stage" class="arch-range"><canvas id="cv" tabindex="0" role="img" aria-describedby="arch-help"></canvas><div class="arch-range-caption"><span id="arch-target-name"></span><span id="arch-distance">12 m · Shot 1 of 3</span></div><div id="arch-impact" hidden><span id="arch-impact-label"></span><strong id="arch-impact-score"></strong><span id="arch-impact-detail"></span></div><div class="arch-sight-wind" id="arch-sight-wind"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true"><path d="M4 12h16m-6-6 6 6-6 6"/></svg><b></b></div></div>
  <div class="arch-bottom"><div><p id="arch-status" role="status">Drag to aim. Release to lock. Then choose strength.</p><p id="arch-help">Each shot is farther away, with stronger wind.<span>Keyboard: arrows to aim, Enter to lock; choose strength, then fire.</span></p></div><div class="arch-shot-controls"><label for="arch-power">2. Choose strength <output id="arch-power-value">70%</output></label><input id="arch-power" type="range" min="35" max="100" value="70"><button class="btn" id="arch-fire">Lock aim</button><button class="arch-text-btn" id="arch-adjust" hidden>Adjust aim</button><button class="btn" id="arch-next" hidden>Next shot</button></div></div>`;
  app.scrollTop = 0;
